// The single place the Twilio body is read. Everything downstream works on this
// flat item, so no later HTTP node can shadow the call facts.
const b = $json.body || {};
const speech = (b.SpeechResult || '').trim();
return [{ json: {
  callSid: b.CallSid || 'unknown',
  from: b.From || 'unknown caller',
  fromName: b.FromName || '',
  to: b.To || '',
  direction: b.Direction || '',
  callStatus: b.CallStatus || '',
  speech,
  recordingUrl: b.RecordingUrl || '',
  dialStatus: b.DialCallStatus || '',
  transcription: (b.TranscriptionText || '').trim(),
  transcriptionStatus: b.TranscriptionStatus || ''
} }];

