// Record the turn, then build the TwiML for this reply. One node so the call
// state and the words on the phone cannot disagree.
const asked = $json || {};
const ctx = $('Pick Agent').first().json || {};
const utterance = ctx.utterance || '';
const agent = ctx.agent || 'greet';

const voice = $env.FRONTLINE_VOICE || 'Polly.Joanna-Neural';
const base = ($env.FRONTLINE_PUBLIC_URL || '').replace(/\/+$/, '');
const action = base ? base + '/webhook/frontline-receptionist' : '';

let reply = (asked.reply || '').trim();
if (!reply) reply = "I'm sorry, I did not catch that. Could you say it again?";

const store = $getWorkflowStaticData('global');
store.calls = store.calls || {};
const session = store.calls[ctx.callSid] || { history: [] };
session.history = session.history || [];
if (utterance) session.history.push({ role: 'caller', content: utterance });
session.history.push({ role: 'assistant', content: reply });
session.history = session.history.slice(-10);
session.updated = Date.now();
session.agent = agent;
store.calls[ctx.callSid] = session;

const say = (s) => String(s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const gather = action
  ? `<Gather input="speech" action="${say(action)}" speechTimeout="auto" timeout="6" language="en-US" />`
  : '<Hangup/>';
const twiml = `<?xml version="1.0" encoding="UTF-8"?><Response><Say voice="${voice}">${say(reply)}</Say>${gather}</Response>`;

// Transfer only if a human is asked for AND a number exists in the environment.
const wantsHuman = /\b(human|person|manager|owner|technician|tech|representative|someone|transfer|speak to|real person)\b/i.test(utterance);
const forwardTo = ($env.FRONTLINE_FORWARD_TO || '').trim();
const forward = wantsHuman && !!forwardTo;

return [{ json: {
  reply, twiml, callSid: ctx.callSid, agent,
  route_reason: ctx.route_reason, forward, forward_to: forwardTo,
  gateway_ok: asked.ok !== false, gateway_mode: asked.mode || '',
  gateway_error: asked.error || ''
} }];
